@pytest.mark.vcr
def test_nyaa_search_pagination(nyaa_client: Nyaa, monkeypatch: pytest.MonkeyPatch) -> None:
    requested_ids: list[int] = []
    releases: list[NyaaRelease] = []

    # Keep real search pages, but avoid downloading every release and torrent.
    def get(page: int) -> NyaaRelease:
        requested_ids.append(page)
        release = cast(NyaaRelease, Mock(spec_set=NyaaRelease, id=page))
        releases.append(release)
        return release

    monkeypatch.setattr(nyaa_client, "get", get)
    results = [release for release in nyaa_client.search('"[SubsPlease]"', order=Order.ASCENDING)]

    # Nyaa displays 1 2 3 4 5 ... 13 14; page 7 must be fetched despite the ellipsis.
    assert len(requested_ids) == 1000
    assert requested_ids == sorted(requested_ids)
    assert (requested_ids[0], requested_ids[74]) == (1286641, 1287710)  # Page 1
    assert (requested_ids[450], requested_ids[524]) == (1293280, 1294390)  # Page 7
    assert (requested_ids[975], requested_ids[-1]) == (1300881, 1301432)  # Page 14
    assert results == releases


@pytest.mark.vcr
def test_nyaa_search_release(nyaa_client: Nyaa) -> None:
    newer, older, *remaining = [release for release in nyaa_client.search('"[MTBB] Your Name"')]

    assert newer.id == 1426521
    assert newer.title == "[MTBB] Your Name. (Dual Audio) (BD 1080p) | Kimi no Na wa. (v2)"
    assert newer.torrent.name == "[MTBB] Kimi no Na wa. (2016) v2 [97681524].mkv"
    assert newer.torrent.infohash == "a5f5c7f8d03da14f8c0b2b1fbcd5328c72cd4772"

    assert older.id == 943215
    assert older.title == "[MTBB] Your Name. (1080p BD) | Kimi no Na wa."
    assert older.torrent.name == "[MTBB] Kimi no Na Wa (1080p BD).mkv"
    assert older.torrent.infohash == "7141c1398195046b44a2a761a3d2a5a67bcb244e"

    assert remaining == []


